begin;
grant delete on public.asb_material_requests to authenticated;
create or replace function public.asb_my_requests() returns jsonb language sql stable security definer set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'project_id',r.project_id,'name',p.name,'content',r.content,'status',r.status,'needed_on',r.needed_on,'urgent',r.urgent) order by r.created_at desc),'[]'::jsonb) from public.asb_material_requests r join public.projects p on p.id=r.project_id where r.employee_id=public.asb_employee() $$;
create or replace function public.asb_edit_request(request_id uuid, site uuid, details text, needed date, priority boolean, remove boolean) returns void language plpgsql security definer set search_path='' as $$ declare emp uuid:=public.asb_employee(); begin if emp is null then raise exception 'Accès interdit'; end if; if remove then delete from public.asb_material_requests where id=request_id and employee_id=emp and status='En attente'; else if not exists(select 1 from public.employee_planning p where p.employee_id=emp and p.project_id=site) then raise exception 'Chantier non autorisé'; end if; update public.asb_material_requests set project_id=site,content=trim(details),needed_on=needed,urgent=priority where id=request_id and employee_id=emp and status='En attente'; end if; if not found then raise exception 'Demande non modifiable'; end if; end $$;
create or replace function public.asb_check_task(task_id uuid, checked boolean) returns void language plpgsql security definer set search_path='' as $$ declare emp uuid:=public.asb_employee(); begin if checked is distinct from true then raise exception 'Validation définitive côté salarié'; end if; update public.asb_tasks t set done_at=now(),done_by=emp where t.id=task_id and t.done_at is null and emp is not null and (t.employee_id is null or t.employee_id=emp) and exists(select 1 from public.employee_planning p where p.task_group=t.task_group and p.employee_id=emp); if not found then raise exception 'Prestation déjà validée ou non autorisée'; end if; end $$;
create table if not exists public.asb_messages(id uuid primary key default gen_random_uuid(),subject text not null check(length(trim(subject)) between 1 and 200),body text not null check(length(trim(body)) between 1 and 8000),priority text not null check(priority in ('Information','Important','Urgent')),created_at timestamptz not null default now());
create table if not exists public.asb_message_recipients(message_id uuid references public.asb_messages(id) on delete cascade,employee_id uuid references public.employees(id),read_at timestamptz,primary key(message_id,employee_id));
alter table public.asb_messages enable row level security;
alter table public.asb_message_recipients enable row level security;
revoke all on public.asb_messages,public.asb_message_recipients from public,anon,authenticated;
grant select on public.asb_messages,public.asb_message_recipients to authenticated;
drop policy if exists asb_messages_admin on public.asb_messages;
create policy asb_messages_admin on public.asb_messages for select to authenticated using(public.asb_role()='admin');
drop policy if exists asb_recipients_admin on public.asb_message_recipients;
create policy asb_recipients_admin on public.asb_message_recipients for select to authenticated using(public.asb_role()='admin');
create or replace function public.asb_send_message(subject_text text,body_text text,importance text, recipients uuid[]) returns void language plpgsql security definer set search_path='' as $$ declare mid uuid; begin if public.asb_role()<>'admin' then raise exception 'Accès interdit'; end if; insert into public.asb_messages(subject,body,priority) values(trim(subject_text),trim(body_text),importance) returning id into mid; insert into public.asb_message_recipients(message_id,employee_id) select mid,e.id from public.employees e where e.id=any(recipients) and coalesce(e.active,true) and not coalesce(e.archived,false); if not found then raise exception 'Aucun destinataire actif'; end if; end $$;
create or replace function public.asb_my_messages() returns jsonb language sql stable security definer set search_path='' as $$ select coalesce(jsonb_agg(to_jsonb(m)||jsonb_build_object('read_at',r.read_at) order by m.created_at desc),'[]'::jsonb) from public.asb_messages m join public.asb_message_recipients r on r.message_id=m.id where r.employee_id=public.asb_employee() $$;
create or replace function public.asb_read_message(mid uuid) returns void language sql security definer set search_path='' as $$ update public.asb_message_recipients set read_at=coalesce(read_at,now()) where message_id=mid and employee_id=public.asb_employee() $$;
revoke all on function public.asb_edit_request(uuid,uuid,text,date,boolean,boolean),public.asb_send_message(text,text,text,uuid[]),public.asb_my_messages(),public.asb_read_message(uuid) from public,anon;
grant execute on function public.asb_edit_request(uuid,uuid,text,date,boolean,boolean),public.asb_send_message(text,text,text,uuid[]),public.asb_my_messages(),public.asb_read_message(uuid) to authenticated;
commit;
